type ColorWheelOwnProps = {
  value?: MuxUIColorValue;
  defaultValue?: MuxUIColorValue;
  onChange?: (value: MuxUIColorValue) => void;
  outerRadius?: number;
  innerRadius?: number;
  disabled?: boolean;
  readOnly?: boolean;
};

type ColorWheelProps = ColorWheelOwnProps & {
  className?: string;
} & MuxUIAriaAccessibleName;

type MuxUIAriaAccessibleName = {
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  'aria-label'?: never;
  'aria-labelledby': string;
};
